"""Compare against outputs generated by the actual Chreode evaluator."""

import json
from pathlib import Path

import pytest

from chreode_case import make_case
from evaluate.evaluate_gears import run_gears_evaluation


@pytest.mark.parametrize("prediction_format", ["npz", "pkl"])
@pytest.mark.parametrize("matrix_kind", ["dense", "sparse"])
@pytest.mark.parametrize("control_dtype", ["float64", "float32"])
def test_matches_original_chreode_evaluator(tmp_path, prediction_format, matrix_kind, control_dtype):
    prediction, truth, vocab = make_case(tmp_path / "inputs", prediction_format, matrix_kind, control_dtype)
    fixture = json.loads((Path(__file__).parent / "fixtures/chreode_reference.json").read_text())
    case = f"{prediction_format}_{matrix_kind}" + ("_float32" if control_dtype == "float32" else "")
    expected = fixture["cases"][case]
    result = run_gears_evaluation(prediction, truth, tmp_path / "scores", gene_vocab=vocab)
    for key in ["de20_mse", "de20_delta_r"]:
        assert result["metrics"][key] == pytest.approx(expected[key], abs=1e-12, rel=1e-12)
    assert result["shared_genes"] == expected["shared_genes"]
    for actual, original in zip(result["per_condition"], expected["conditions"]):
        assert actual["condition"] == original["condition"]
        assert actual["de_genes"] == original["de_genes"]
        for key in ["de20_mse", "de20_delta_r"]:
            assert actual[key] == pytest.approx(original[key], abs=1e-12, rel=1e-12)
